window.__code__["base-py-438"] = {"code_id": "base-py-438", "kind": "src", "title": "_base.py:438", "source_path": "agentscope/src/agentscope/middleware/_base.py", "highlight_line": 438, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># -*- coding: utf-8 -*-</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Base middleware class for AgentScope middleware system.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-kw\">from</span> typing <span class=\"c-kw\">import</span> AsyncGenerator, Awaitable, Callable, TYPE_CHECKING</span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..tool <span class=\"c-kw\">import</span> ToolBase</span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\"><span class=\"c-kw\">if</span> TYPE_CHECKING:</span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\">    <span class=\"c-kw\">from</span> ..agent <span class=\"c-kw\">import</span> Agent</span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\">    <span class=\"c-kw\">from</span> ..model <span class=\"c-kw\">import</span> ChatResponse</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\"><span class=\"c-kw\">class</span> MiddlewareBase:  <span class=\"c-com\"># pylint: disable=unused-argument</span></span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Base <span class=\"c-kw\">class</span> <span class=\"c-kw\">for</span> all middleware implementations.</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">    Middleware provides interception mechanisms at 5 key execution points</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">    <span class=\"c-kw\">in</span> the Agent lifecycle:</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\">    **Onion Pattern Hooks** (<span class=\"c-kw\">with</span> before/after logic):</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\">    - `on_reply`: Intercepts the entire reply process</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">    - `on_reasoning`: Intercepts the reasoning/model call phase</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">    - `on_acting`: Intercepts individual tool call execution</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">    - `on_model_call`: Intercepts the raw model API call</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">    **Transformer Pattern Hook** (sequential pipeline):</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">    - `on_system_prompt`: Transforms the system prompt string</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">    Each hook <span class=\"c-kw\">is</span> optional - only implement the ones you need. The middleware</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">    system will automatically detect which hooks are implemented at runtime.</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">    Example:</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">        ```python</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">        <span class=\"c-kw\">class</span> LoggingMiddleware(MiddlewareBase):</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">            <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_reasoning(</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">                <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">                agent: Agent,</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">                input_kwargs: dict,</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">                next_handler: Callable[[], AsyncGenerator],</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">            ) -&gt; AsyncGenerator:</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">                print(f<span class=\"c-str\">&quot;Before reasoning for agent {agent.name}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">                <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> event <span class=\"c-kw\">in</span> next_handler():</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">                    <span class=\"c-kw\">yield</span> event</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">                print(f<span class=\"c-str\">&quot;After reasoning for agent {agent.name}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">        agent = Agent(</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">            ...</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">            middlewares=[LoggingMiddleware()],</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">            ...</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">        ```</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> is_implemented(<span class=\"c-kw\">self</span>, hook_name: str) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Check <span class=\"c-kw\">if</span> a hook method <span class=\"c-kw\">is</span> implemented <span class=\"c-kw\">in</span> the subclass.</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">            hook_name: Name of the hook method to check</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">            <span class=\"c-kw\">True</span> <span class=\"c-kw\">if</span> the hook <span class=\"c-kw\">is</span> implemented (overridden), <span class=\"c-kw\">False</span> otherwise</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">        base_method = getattr(MiddlewareBase, hook_name, <span class=\"c-kw\">None</span>)</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">        sub_method = getattr(type(<span class=\"c-kw\">self</span>), hook_name, <span class=\"c-kw\">None</span>)</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> base_method <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> sub_method</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_reply(</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">        agent: <span class=\"c-str\">&quot;Agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">        input_kwargs: dict,</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">        next_handler: Callable[..., AsyncGenerator],</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">    ) -&gt; AsyncGenerator:</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Hook <span class=\"c-kw\">for</span> intercepting the reply process.</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">            agent: The Agent instance executing this middleware</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">            input_kwargs: Dictionary containing:</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">                - inputs: Msg | list[Msg] | UserConfirmResultEvent |</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">                ExternalExecutionResultEvent | <span class=\"c-kw\">None</span> — the unified inputs</span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">                that trigger this reply (new message(s), a resumption</span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">                event <span class=\"c-kw\">from</span> a previous outside interaction, <span class=\"c-kw\">or</span> <span class=\"c-kw\">None</span>).</span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\">            next_handler: Callable that executes the next middleware <span class=\"c-kw\">or</span></span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">             original method</span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">        Yields:</span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">            AgentEvent | Msg: Events <span class=\"c-kw\">from</span> the reply process</span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">        <span class=\"c-kw\">raise</span> RuntimeError(</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;{type(self).__name__} does not implement on_reply&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">        <span class=\"c-kw\">yield</span>  <span class=\"c-com\"># pylint: disable=unreachable</span></span></div>\n<div class=\"c-line\" data-line=\"90\"><span class=\"c-no\">90</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"91\"><span class=\"c-no\">91</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_reasoning(</span></div>\n<div class=\"c-line\" data-line=\"92\"><span class=\"c-no\">92</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"93\"><span class=\"c-no\">93</span><span class=\"c-src\">        agent: <span class=\"c-str\">&quot;Agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"94\"><span class=\"c-no\">94</span><span class=\"c-src\">        input_kwargs: dict,</span></div>\n<div class=\"c-line\" data-line=\"95\"><span class=\"c-no\">95</span><span class=\"c-src\">        next_handler: Callable[..., AsyncGenerator],</span></div>\n<div class=\"c-line\" data-line=\"96\"><span class=\"c-no\">96</span><span class=\"c-src\">    ) -&gt; AsyncGenerator:</span></div>\n<div class=\"c-line\" data-line=\"97\"><span class=\"c-no\">97</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Hook <span class=\"c-kw\">for</span> intercepting the reasoning process.</span></div>\n<div class=\"c-line\" data-line=\"98\"><span class=\"c-no\">98</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"99\"><span class=\"c-no\">99</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"100\"><span class=\"c-no\">100</span><span class=\"c-src\">            agent: The Agent instance executing this middleware</span></div>\n<div class=\"c-line\" data-line=\"101\"><span class=\"c-no\">101</span><span class=\"c-src\">            input_kwargs: Dictionary containing:</span></div>\n<div class=\"c-line\" data-line=\"102\"><span class=\"c-no\">102</span><span class=\"c-src\">                - tool_choice: ToolChoice (default <span class=\"c-kw\">None</span>)</span></div>\n<div class=\"c-line\" data-line=\"103\"><span class=\"c-no\">103</span><span class=\"c-src\">            next_handler: Callable that executes the next middleware <span class=\"c-kw\">or</span></span></div>\n<div class=\"c-line\" data-line=\"104\"><span class=\"c-no\">104</span><span class=\"c-src\">            original method</span></div>\n<div class=\"c-line\" data-line=\"105\"><span class=\"c-no\">105</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"106\"><span class=\"c-no\">106</span><span class=\"c-src\">        Yields:</span></div>\n<div class=\"c-line\" data-line=\"107\"><span class=\"c-no\">107</span><span class=\"c-src\">            Various events <span class=\"c-kw\">from</span> the reasoning process</span></div>\n<div class=\"c-line\" data-line=\"108\"><span class=\"c-no\">108</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"109\"><span class=\"c-no\">109</span><span class=\"c-src\">        <span class=\"c-kw\">raise</span> RuntimeError(</span></div>\n<div class=\"c-line\" data-line=\"110\"><span class=\"c-no\">110</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;{type(self).__name__} does not implement on_reasoning&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"111\"><span class=\"c-no\">111</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"112\"><span class=\"c-no\">112</span><span class=\"c-src\">        <span class=\"c-kw\">yield</span>  <span class=\"c-com\"># pylint: disable=unreachable</span></span></div>\n<div class=\"c-line\" data-line=\"113\"><span class=\"c-no\">113</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"114\"><span class=\"c-no\">114</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_acting(</span></div>\n<div class=\"c-line\" data-line=\"115\"><span class=\"c-no\">115</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"116\"><span class=\"c-no\">116</span><span class=\"c-src\">        agent: <span class=\"c-str\">&quot;Agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"117\"><span class=\"c-no\">117</span><span class=\"c-src\">        input_kwargs: dict,</span></div>\n<div class=\"c-line\" data-line=\"118\"><span class=\"c-no\">118</span><span class=\"c-src\">        next_handler: Callable[..., AsyncGenerator],</span></div>\n<div class=\"c-line\" data-line=\"119\"><span class=\"c-no\">119</span><span class=\"c-src\">    ) -&gt; AsyncGenerator:</span></div>\n<div class=\"c-line\" data-line=\"120\"><span class=\"c-no\">120</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Hook <span class=\"c-kw\">for</span> intercepting the raw tool execution.</span></div>\n<div class=\"c-line\" data-line=\"121\"><span class=\"c-no\">121</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"122\"><span class=\"c-no\">122</span><span class=\"c-src\">        This hook wraps **only** the ``toolkit.call_tool`` call — i.e. the</span></div>\n<div class=\"c-line\" data-line=\"123\"><span class=\"c-no\">123</span><span class=\"c-src\">        pure I/O execution layer.  Permission checking, input validation, <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"124\"><span class=\"c-no\">124</span><span class=\"c-src\">        context writes are handled by the agent **outside** this hook <span class=\"c-kw\">and</span> are</span></div>\n<div class=\"c-line\" data-line=\"125\"><span class=\"c-no\">125</span><span class=\"c-src\">        therefore <span class=\"c-kw\">not</span> visible here.</span></div>\n<div class=\"c-line\" data-line=\"126\"><span class=\"c-no\">126</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"127\"><span class=\"c-no\">127</span><span class=\"c-src\">        This separation makes it safe to offload the ``next_handler``</span></div>\n<div class=\"c-line\" data-line=\"128\"><span class=\"c-no\">128</span><span class=\"c-src\">        coroutine to a background task: it will never mutate agent context</span></div>\n<div class=\"c-line\" data-line=\"129\"><span class=\"c-no\">129</span><span class=\"c-src\">        on its own.</span></div>\n<div class=\"c-line\" data-line=\"130\"><span class=\"c-no\">130</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"131\"><span class=\"c-no\">131</span><span class=\"c-src\">        .. note::</span></div>\n<div class=\"c-line\" data-line=\"132\"><span class=\"c-no\">132</span><span class=\"c-src\">            Tools <span class=\"c-kw\">with</span> ``is_state_injected=<span class=\"c-kw\">True</span>`` receive the live</span></div>\n<div class=\"c-line\" data-line=\"133\"><span class=\"c-no\">133</span><span class=\"c-src\">            ``agent.state`` object.  Offloading such tools to a background</span></div>\n<div class=\"c-line\" data-line=\"134\"><span class=\"c-no\">134</span><span class=\"c-src\">            task may cause concurrent state mutations — guard against this</span></div>\n<div class=\"c-line\" data-line=\"135\"><span class=\"c-no\">135</span><span class=\"c-src\">            <span class=\"c-kw\">in</span> your middleware implementation.</span></div>\n<div class=\"c-line\" data-line=\"136\"><span class=\"c-no\">136</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"137\"><span class=\"c-no\">137</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"138\"><span class=\"c-no\">138</span><span class=\"c-src\">            agent (`Agent`):</span></div>\n<div class=\"c-line\" data-line=\"139\"><span class=\"c-no\">139</span><span class=\"c-src\">                The Agent instance executing this middleware.</span></div>\n<div class=\"c-line\" data-line=\"140\"><span class=\"c-no\">140</span><span class=\"c-src\">            input_kwargs (`dict`):</span></div>\n<div class=\"c-line\" data-line=\"141\"><span class=\"c-no\">141</span><span class=\"c-src\">                Dictionary containing:</span></div>\n<div class=\"c-line\" data-line=\"142\"><span class=\"c-no\">142</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"143\"><span class=\"c-no\">143</span><span class=\"c-src\">                - ``tool_call`` (``ToolCallBlock``): the tool call to execute.</span></div>\n<div class=\"c-line\" data-line=\"144\"><span class=\"c-no\">144</span><span class=\"c-src\">                  By the time this hook <span class=\"c-kw\">is</span> invoked the tool call has already</span></div>\n<div class=\"c-line\" data-line=\"145\"><span class=\"c-no\">145</span><span class=\"c-src\">                  been validated <span class=\"c-kw\">and</span> permitted.</span></div>\n<div class=\"c-line\" data-line=\"146\"><span class=\"c-no\">146</span><span class=\"c-src\">            next_handler (`Callable[..., AsyncGenerator]`):</span></div>\n<div class=\"c-line\" data-line=\"147\"><span class=\"c-no\">147</span><span class=\"c-src\">                Callable that executes the next middleware <span class=\"c-kw\">or</span></span></div>\n<div class=\"c-line\" data-line=\"148\"><span class=\"c-no\">148</span><span class=\"c-src\">                ``_acting_impl``.</span></div>\n<div class=\"c-line\" data-line=\"149\"><span class=\"c-no\">149</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"150\"><span class=\"c-no\">150</span><span class=\"c-src\">        Yields:</span></div>\n<div class=\"c-line\" data-line=\"151\"><span class=\"c-no\">151</span><span class=\"c-src\">            `ToolChunk | ToolResponse`:</span></div>\n<div class=\"c-line\" data-line=\"152\"><span class=\"c-no\">152</span><span class=\"c-src\">                Intermediate ``ToolChunk`` objects followed by a final</span></div>\n<div class=\"c-line\" data-line=\"153\"><span class=\"c-no\">153</span><span class=\"c-src\">                ``ToolResponse`` produced by the tool.</span></div>\n<div class=\"c-line\" data-line=\"154\"><span class=\"c-no\">154</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"155\"><span class=\"c-no\">155</span><span class=\"c-src\">        <span class=\"c-kw\">raise</span> RuntimeError(</span></div>\n<div class=\"c-line\" data-line=\"156\"><span class=\"c-no\">156</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;{type(self).__name__} does not implement on_acting&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"157\"><span class=\"c-no\">157</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"158\"><span class=\"c-no\">158</span><span class=\"c-src\">        <span class=\"c-kw\">yield</span>  <span class=\"c-com\"># pylint: disable=unreachable</span></span></div>\n<div class=\"c-line\" data-line=\"159\"><span class=\"c-no\">159</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"160\"><span class=\"c-no\">160</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_model_call(</span></div>\n<div class=\"c-line\" data-line=\"161\"><span class=\"c-no\">161</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"162\"><span class=\"c-no\">162</span><span class=\"c-src\">        agent: <span class=\"c-str\">&quot;Agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"163\"><span class=\"c-no\">163</span><span class=\"c-src\">        input_kwargs: dict,</span></div>\n<div class=\"c-line\" data-line=\"164\"><span class=\"c-no\">164</span><span class=\"c-src\">        next_handler: Callable[</span></div>\n<div class=\"c-line\" data-line=\"165\"><span class=\"c-no\">165</span><span class=\"c-src\">            ...,</span></div>\n<div class=\"c-line\" data-line=\"166\"><span class=\"c-no\">166</span><span class=\"c-src\">            Awaitable[<span class=\"c-str\">&quot;ChatResponse&quot;</span> | AsyncGenerator[<span class=\"c-str\">&quot;ChatResponse&quot;</span>, <span class=\"c-kw\">None</span>]],</span></div>\n<div class=\"c-line\" data-line=\"167\"><span class=\"c-no\">167</span><span class=\"c-src\">        ],</span></div>\n<div class=\"c-line\" data-line=\"168\"><span class=\"c-no\">168</span><span class=\"c-src\">    ) -&gt; <span class=\"c-str\">&quot;ChatResponse&quot;</span> | AsyncGenerator[<span class=\"c-str\">&quot;ChatResponse&quot;</span>, <span class=\"c-kw\">None</span>]:</span></div>\n<div class=\"c-line\" data-line=\"169\"><span class=\"c-no\">169</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Hook <span class=\"c-kw\">for</span> intercepting the model API call.</span></div>\n<div class=\"c-line\" data-line=\"170\"><span class=\"c-no\">170</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"171\"><span class=\"c-no\">171</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"172\"><span class=\"c-no\">172</span><span class=\"c-src\">            agent: The Agent instance executing this middleware</span></div>\n<div class=\"c-line\" data-line=\"173\"><span class=\"c-no\">173</span><span class=\"c-src\">            input_kwargs: Dictionary containing:</span></div>\n<div class=\"c-line\" data-line=\"174\"><span class=\"c-no\">174</span><span class=\"c-src\">                - messages: list[Msg]</span></div>\n<div class=\"c-line\" data-line=\"175\"><span class=\"c-no\">175</span><span class=\"c-src\">                - tools: list[dict]</span></div>\n<div class=\"c-line\" data-line=\"176\"><span class=\"c-no\">176</span><span class=\"c-src\">                - tool_choice: ToolChoice</span></div>\n<div class=\"c-line\" data-line=\"177\"><span class=\"c-no\">177</span><span class=\"c-src\">                - current_model: The model instance used <span class=\"c-kw\">for</span> this call</span></div>\n<div class=\"c-line\" data-line=\"178\"><span class=\"c-no\">178</span><span class=\"c-src\">            next_handler: Callable that executes the next middleware <span class=\"c-kw\">or</span></span></div>\n<div class=\"c-line\" data-line=\"179\"><span class=\"c-no\">179</span><span class=\"c-src\">            original method</span></div>\n<div class=\"c-line\" data-line=\"180\"><span class=\"c-no\">180</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"181\"><span class=\"c-no\">181</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"182\"><span class=\"c-no\">182</span><span class=\"c-src\">            ChatResponse <span class=\"c-kw\">or</span> AsyncGenerator[ChatResponse, <span class=\"c-kw\">None</span>]</span></div>\n<div class=\"c-line\" data-line=\"183\"><span class=\"c-no\">183</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"184\"><span class=\"c-no\">184</span><span class=\"c-src\">        <span class=\"c-kw\">raise</span> RuntimeError(</span></div>\n<div class=\"c-line\" data-line=\"185\"><span class=\"c-no\">185</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;{type(self).__name__} does not implement on_model_call&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"186\"><span class=\"c-no\">186</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"187\"><span class=\"c-no\">187</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"188\"><span class=\"c-no\">188</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_compress_context(</span></div>\n<div class=\"c-line\" data-line=\"189\"><span class=\"c-no\">189</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"190\"><span class=\"c-no\">190</span><span class=\"c-src\">        agent: <span class=\"c-str\">&quot;Agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"191\"><span class=\"c-no\">191</span><span class=\"c-src\">        input_kwargs: dict,</span></div>\n<div class=\"c-line\" data-line=\"192\"><span class=\"c-no\">192</span><span class=\"c-src\">        next_handler: Callable[..., Awaitable[<span class=\"c-kw\">None</span>]],</span></div>\n<div class=\"c-line\" data-line=\"193\"><span class=\"c-no\">193</span><span class=\"c-src\">    ) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"194\"><span class=\"c-no\">194</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Onion hook <span class=\"c-kw\">for</span> `compress_context` function <span class=\"c-kw\">in</span> `Agent` <span class=\"c-kw\">class</span></span></div>\n<div class=\"c-line\" data-line=\"195\"><span class=\"c-no\">195</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"196\"><span class=\"c-no\">196</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"197\"><span class=\"c-no\">197</span><span class=\"c-src\">            agent (`Agent`):</span></div>\n<div class=\"c-line\" data-line=\"198\"><span class=\"c-no\">198</span><span class=\"c-src\">                The Agent instance executing this middleware</span></div>\n<div class=\"c-line\" data-line=\"199\"><span class=\"c-no\">199</span><span class=\"c-src\">            input_kwargs (`dict`):</span></div>\n<div class=\"c-line\" data-line=\"200\"><span class=\"c-no\">200</span><span class=\"c-src\">                Dictionary containing:</span></div>\n<div class=\"c-line\" data-line=\"201\"><span class=\"c-no\">201</span><span class=\"c-src\">                - context_config: ContextConfig | <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"202\"><span class=\"c-no\">202</span><span class=\"c-src\">                - instructions: HintBlock | <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"203\"><span class=\"c-no\">203</span><span class=\"c-src\">            next_handler (`Callable[..., Awaitable[<span class=\"c-kw\">None</span>]]`):</span></div>\n<div class=\"c-line\" data-line=\"204\"><span class=\"c-no\">204</span><span class=\"c-src\">                Callable that executes the next middleware <span class=\"c-kw\">or</span></span></div>\n<div class=\"c-line\" data-line=\"205\"><span class=\"c-no\">205</span><span class=\"c-src\">                original method</span></div>\n<div class=\"c-line\" data-line=\"206\"><span class=\"c-no\">206</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"207\"><span class=\"c-no\">207</span><span class=\"c-src\">        <span class=\"c-kw\">raise</span> RuntimeError(</span></div>\n<div class=\"c-line\" data-line=\"208\"><span class=\"c-no\">208</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;{type(self).__name__} does not implement on_compress_context&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"209\"><span class=\"c-no\">209</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"210\"><span class=\"c-no\">210</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"211\"><span class=\"c-no\">211</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_system_prompt(</span></div>\n<div class=\"c-line\" data-line=\"212\"><span class=\"c-no\">212</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"213\"><span class=\"c-no\">213</span><span class=\"c-src\">        agent: <span class=\"c-str\">&quot;Agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"214\"><span class=\"c-no\">214</span><span class=\"c-src\">        current_prompt: str,</span></div>\n<div class=\"c-line\" data-line=\"215\"><span class=\"c-no\">215</span><span class=\"c-src\">    ) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"216\"><span class=\"c-no\">216</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Transform the system prompt string.</span></div>\n<div class=\"c-line\" data-line=\"217\"><span class=\"c-no\">217</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"218\"><span class=\"c-no\">218</span><span class=\"c-src\">        This uses a transformer/pipeline pattern rather than onion pattern.</span></div>\n<div class=\"c-line\" data-line=\"219\"><span class=\"c-no\">219</span><span class=\"c-src\">        Multiple middlewares are applied sequentially, each receiving the</span></div>\n<div class=\"c-line\" data-line=\"220\"><span class=\"c-no\">220</span><span class=\"c-src\">        output of the previous one.</span></div>\n<div class=\"c-line\" data-line=\"221\"><span class=\"c-no\">221</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"222\"><span class=\"c-no\">222</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"223\"><span class=\"c-no\">223</span><span class=\"c-src\">            agent: The Agent instance executing this middleware</span></div>\n<div class=\"c-line\" data-line=\"224\"><span class=\"c-no\">224</span><span class=\"c-src\">            current_prompt: The current system prompt string</span></div>\n<div class=\"c-line\" data-line=\"225\"><span class=\"c-no\">225</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"226\"><span class=\"c-no\">226</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"227\"><span class=\"c-no\">227</span><span class=\"c-src\">            str: The transformed system prompt</span></div>\n<div class=\"c-line\" data-line=\"228\"><span class=\"c-no\">228</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"229\"><span class=\"c-no\">229</span><span class=\"c-src\">        <span class=\"c-kw\">raise</span> RuntimeError(</span></div>\n<div class=\"c-line\" data-line=\"230\"><span class=\"c-no\">230</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;{type(self).__name__} does not implement on_system_prompt&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"231\"><span class=\"c-no\">231</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"232\"><span class=\"c-no\">232</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"233\"><span class=\"c-no\">233</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> list_tools(<span class=\"c-kw\">self</span>) -&gt; list[ToolBase]:</span></div>\n<div class=\"c-line\" data-line=\"234\"><span class=\"c-no\">234</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;List available tools provided by this middleware. Optional to</span></div>\n<div class=\"c-line\" data-line=\"235\"><span class=\"c-no\">235</span><span class=\"c-src\">        implement.</span></div>\n<div class=\"c-line\" data-line=\"236\"><span class=\"c-no\">236</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"237\"><span class=\"c-no\">237</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"238\"><span class=\"c-no\">238</span><span class=\"c-src\">            `list[ToolBase]`:</span></div>\n<div class=\"c-line\" data-line=\"239\"><span class=\"c-no\">239</span><span class=\"c-src\">                A list of tools provided by this middleware.</span></div>\n<div class=\"c-line\" data-line=\"240\"><span class=\"c-no\">240</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"241\"><span class=\"c-no\">241</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> []</span></div>\n<div class=\"c-line\" data-line=\"242\"><span class=\"c-no\">242</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"243\"><span class=\"c-no\">243</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> get_middleware_key(<span class=\"c-kw\">self</span>) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"244\"><span class=\"c-no\">244</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Get the unique key <span class=\"c-kw\">for</span> this middleware, used to save middleware</span></div>\n<div class=\"c-line\" data-line=\"245\"><span class=\"c-no\">245</span><span class=\"c-src\">        states <span class=\"c-kw\">in</span> `AgentState` instances.</span></div>\n<div class=\"c-line\" data-line=\"246\"><span class=\"c-no\">246</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"247\"><span class=\"c-no\">247</span><span class=\"c-src\">        Optionally, middleware classes can override this method to</span></div>\n<div class=\"c-line\" data-line=\"248\"><span class=\"c-no\">248</span><span class=\"c-src\">        provide their own unique key.</span></div>\n<div class=\"c-line\" data-line=\"249\"><span class=\"c-no\">249</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"250\"><span class=\"c-no\">250</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">self</span>.__class__.__name__</span></div>\n<div class=\"c-line\" data-line=\"251\"><span class=\"c-no\">251</span><span class=\"c-src\">&nbsp;</span></div>\n</div>", "lines": 251, "explanation": "_base.py 来自 agentscope/QwenPaw 框架源码。结合左侧源码与右侧知识点理解此处设计意图；点「反向链接」可回到引用它的教程章节。", "knowledge_points": [], "related_docs": ["W01-Python异步与LLM-API调用"]};
